package dev.workshopvideo;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.ColorDrawable;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.nio.file.*;
/** Drives offsets through WindowManager into the actually bound WallpaperService, only in AOSP. */
public final class WallpaperServiceChecks extends Instrumentation {
 private VideoApp app;private WallpaperManager manager;private Activity host;private File output;private int checks;private JSONArray passed=new JSONArray();private boolean xrayOnly,inputOnly;private long maxMainDelay;private boolean heartbeats;private final Handler heartbeat=new Handler(Looper.getMainLooper());private final Runnable pulse=new Runnable(){private long last;public void run(){long now=SystemClock.elapsedRealtime();if(last!=0)maxMainDelay=Math.max(maxMainDelay,now-last);last=now;if(heartbeats)heartbeat.postDelayed(this,16);}};
 public void onCreate(Bundle args){super.onCreate(args);xrayOnly=args!=null&&"true".equals(args.getString("xrayOnly"));inputOnly=args!=null&&"true".equals(args.getString("inputOnly"));start();}
 private void check(boolean ok,String text)throws Exception{if(!ok)throw new AssertionError(text);checks++;passed.put(text);if(output!=null)Files.write(new File(output,"progress.txt").toPath(),(checks+" "+text).getBytes(java.nio.charset.StandardCharsets.UTF_8));android.util.Log.i("ServiceChecks","PASS "+text);}
 private void save(Bitmap image,String name)throws Exception{try(FileOutputStream out=new FileOutputStream(new File(output,name))){image.compress(Bitmap.CompressFormat.PNG,100,out);}}
 private JSONObject configuration(String id)throws Exception{return WallpaperStore.stage(app,app.video(id),"Emulator service paging",false,true,1,new JSONObject().put("zoom",1).put("pan",true).put("scrollStrength",.5));}
 private void shell(String command)throws Exception{try(ParcelFileDescriptor fd=getUiAutomation().executeShellCommand(command);InputStream in=new FileInputStream(fd.getFileDescriptor())){byte[] buffer=new byte[4096];while(in.read(buffer)!=-1){}}}
 private void frames(String id,String kind,int[] counts)throws Exception{
  JSONObject config=configuration(id);WallpaperStore.activate(app,config);long deadline=SystemClock.elapsedRealtime()+60000;while(!WallpaperStore.matchesRendered(app,1,config.getString("file"))&&SystemClock.elapsedRealtime()<deadline)Thread.sleep(200);check(WallpaperStore.matchesRendered(app,1,config.getString("file")),kind+" service produces a committed frame");
  for(int count:counts){for(int page=0;page<count;page++){float offset=page/(count-1f);shell("am start -W -n dev.workshopvideo.test/dev.workshopvideo.OffsetHostActivity --ei pages "+count+" --ei page "+page);Bitmap screenshot=null;boolean correct=false;int actual=-1;long end=SystemClock.elapsedRealtime()+30000;
    while(SystemClock.elapsedRealtime()<end){if(screenshot!=null)screenshot.recycle();screenshot=getUiAutomation().takeScreenshot();if(screenshot!=null){float w=screenshot.getWidth(),h=screenshot.getHeight(),scale=Math.max(w/1440f,h/960f),visible=w/scale;int expected=Math.round((visible/2+(1440-visible)*offset)*255/1439);int pixel=screenshot.getPixel(screenshot.getWidth()/2,screenshot.getHeight()/2);actual=Color.red(pixel);if(Math.abs(expected-actual)<=15&&Color.green(pixel)>10){correct=true;break;}}Thread.sleep(300);}
    check(correct,kind+" WindowManager offsets "+page+"/"+count+" reaches segment red="+actual);save(screenshot,kind+"-"+count+"-"+page+".png");screenshot.recycle();
   }check(WallpaperStore.prefs(app).getInt("launcherPages",0)==count,kind+" engine receives actual framework page-count step "+count);}
 }
 private android.service.wallpaper.WallpaperService.Engine engine()throws Exception{Class<?> thread=Class.forName("android.app.ActivityThread");Object current=thread.getDeclaredMethod("currentActivityThread").invoke(null);java.lang.reflect.Field services=thread.getDeclaredField("mServices");services.setAccessible(true);for(Object service:((java.util.Map<?,?>)services.get(current)).values())if(service instanceof VideoWallpaperService){java.lang.reflect.Field engines=android.service.wallpaper.WallpaperService.class.getDeclaredField("mActiveEngines");engines.setAccessible(true);for(Object e:(java.util.List<?>)engines.get(service))if(!((android.service.wallpaper.WallpaperService.Engine)e).isPreview()&&((android.service.wallpaper.WallpaperService.Engine)e).isVisible())return (android.service.wallpaper.WallpaperService.Engine)e;}throw new AssertionError("running production engine missing");}
 private void touch(float x,float y,int action)throws Exception{android.service.wallpaper.WallpaperService.Engine engine=engine();Rect rect=engine.getSurfaceHolder().getSurfaceFrame();runOnMainSync(()->{MotionEvent event=MotionEvent.obtain(SystemClock.uptimeMillis(),SystemClock.uptimeMillis(),action,x*rect.width(),y*rect.height(),0);engine.onTouchEvent(event);event.recycle();});java.lang.reflect.Field r=engine.getClass().getDeclaredField("renderer");r.setAccessible(true);WallpaperRenderer renderer=(WallpaperRenderer)r.get(engine);java.lang.reflect.Field hf=WallpaperRenderer.class.getDeclaredField("handler");hf.setAccessible(true);java.util.concurrent.CountDownLatch done=new java.util.concurrent.CountDownLatch(1);((Handler)hf.get(renderer)).post(()->{try{java.lang.reflect.Field field=WallpaperRenderer.class.getDeclaredField("effects");field.setAccessible(true);WallpaperEffects fx=(WallpaperEffects)field.get(renderer);Files.write(new File(output,"touch-state-"+action+".txt").toPath(),("engine="+engine+" renderer="+renderer+" fx="+fx+" down="+fx.pointerDown()+" options="+fx.options).getBytes(java.nio.charset.StandardCharsets.UTF_8));}catch(Exception e){}finally{done.countDown();}});if(!done.await(20,java.util.concurrent.TimeUnit.SECONDS))throw new AssertionError("render thread touch queue stalled");}
 private Bitmap shot()throws Exception{Bitmap image=getUiAutomation().takeScreenshot();if(image==null)throw new AssertionError("screenshot missing");return image;}
 private int red(){Bitmap frame=getUiAutomation().takeScreenshot();if(frame==null)return -1;int value=Color.red(frame.getPixel(frame.getWidth()/2,frame.getHeight()/2));frame.recycle();return value;}
 private void frozenOffset()throws Exception{
  android.service.wallpaper.WallpaperService.Engine engine=engine();runOnMainSync(()->engine.onOffsetsChanged(1,.5f,0,0,0,0));Thread.sleep(400);runOnMainSync(()->engine.onOffsetsChanged(1,.5f,0,0,0,0));int before=red();Thread.sleep(250);touch(.1f,.5f,0);touch(.5f,.5f,2);Thread.sleep(200);touch(.9f,.5f,2);Thread.sleep(200);touch(.9f,.5f,1);Thread.sleep(700);int after=red();check(after<before-25,"fixed right endpoint responds to relative wallpaper swipe: "+before+" -> "+after);runOnMainSync(()->engine.onOffsetsChanged(1,.5f,0,0,0,0));Thread.sleep(500);check(Math.abs(red()-after)<12,"fixed callback cannot snap fallback back to right edge");save(shot(),"fixed-offset-fallback.png");
 }
 private void realXray()throws Exception{
  String id="dddddddddddddddddddddddddddddddd";File target=app.video(id);target.getParentFile().mkdirs();try(InputStream in=getContext().getAssets().open("real-xray.zip")){Files.copy(in,target.toPath(),StandardCopyOption.REPLACE_EXISTING);}JSONObject record=new JSONObject().put("id",id).put("kind","scene").put("state","saved").put("storage","private").put("compatible",true).put("title","Real X-ray regression");app.save(record);
  for(int round=0;round<3;round++){
   JSONObject config=WallpaperStore.stage(app,target,"Real X-ray",false,false,1,new JSONObject().put("zoom",1).put("xray",true).put("xraySize",.7));long start=SystemClock.elapsedRealtime();WallpaperStore.activate(app,config);long deadline=start+60000;while(!WallpaperStore.matchesRendered(app,1,config.getString("file"))&&SystemClock.elapsedRealtime()<deadline)Thread.sleep(100);check(WallpaperStore.matchesRendered(app,1,config.getString("file")),"real workshop X-ray renders on service, round "+round);
   shell("am start -W -n dev.workshopvideo.test/dev.workshopvideo.OffsetHostActivity --ei pages 3 --ei page 1");Thread.sleep(350);Bitmap off=shot();touch(.5f,.5f,0);touch(.52f,.5f,2);Thread.sleep(1200);android.service.wallpaper.WallpaperService.Engine activeEngine=engine();java.lang.reflect.Field rendererField=activeEngine.getClass().getDeclaredField("renderer");rendererField.setAccessible(true);WallpaperRenderer renderer=(WallpaperRenderer)rendererField.get(activeEngine);java.lang.reflect.Field effectField=WallpaperRenderer.class.getDeclaredField("effects");effectField.setAccessible(true);WallpaperEffects effect=(WallpaperEffects)effectField.get(renderer);check(effect.pointerDown(),"real X-ray engine retains pressed pointer");Bitmap on=shot();int different=0;for(int y=on.getHeight()/4;y<on.getHeight()*3/4;y+=2)for(int x=on.getWidth()/4;x<on.getWidth()*3/4;x+=2){int a=on.getPixel(x,y),b=off.getPixel(x,y);if(Math.abs(Color.red(a)-Color.red(b))+Math.abs(Color.green(a)-Color.green(b))+Math.abs(Color.blue(a)-Color.blue(b))>30)different++;}save(off,"real-xray-off-"+round+".png");save(on,"real-xray-on-"+round+".png");check(different>200,"touch actually reveals real X-ray pixels before switch, round "+round+" pixels="+different);save(on,"real-xray-touch-"+round+".png");off.recycle();on.recycle();
   frames("cccccccccccccccccccccccccccccccc","video-after-xray-"+round,new int[]{3});check(rendererField.get(engine())==renderer,"X-ray to video keeps one renderer and EGL Surface, round "+round);touch(.52f,.5f,1);
  }
 }
 private void realInput()throws Exception{
  shell("am start -W -n dev.workshopvideo.test/dev.workshopvideo.OffsetHostActivity --ei pages 3 --ei page 1");Thread.sleep(800);Bitmap frame=null;int before=-1;long end=SystemClock.elapsedRealtime()+15000;while(SystemClock.elapsedRealtime()<end){if(frame!=null)frame.recycle();frame=shot();int pixel=frame.getPixel(frame.getWidth()/2,frame.getHeight()/2);before=Color.red(pixel);if(before>25&&before<230&&Color.green(pixel)>15)break;Thread.sleep(300);}save(frame,"real-input-before.png");check(before>25&&before<230,"actual input test starts with a loaded video frame: red="+before);int w=frame.getWidth(),h=frame.getHeight();frame.recycle();android.service.wallpaper.WallpaperService.Engine e=engine();float fixed=before<85?0:before>170?1:.5f;runOnMainSync(()->e.onOffsetsChanged(fixed,.5f,0,0,0,0));Thread.sleep(250);boolean goRight=before<128;long down=SystemClock.uptimeMillis();for(int i=0;i<=12;i++){int action=i==0?0:i==12?1:2;float x=goRight?.9f-.8f*i/12:.1f+.8f*i/12;MotionEvent event=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,w*x,h*.5f,0);event.setSource(InputDevice.SOURCE_TOUCHSCREEN);boolean accepted=getUiAutomation().injectInputEvent(event,true);event.recycle();if(!accepted)throw new AssertionError("actual input delivery refused");Thread.sleep(40);}Thread.sleep(800);int after=red();frame=shot();save(frame,"real-input-after.png");frame.recycle();check(Math.abs(after-before)>25,"real WindowManager touchscreen swipe moves fixed-offset video: "+before+" -> "+after);
 }
 private void resumeCheck()throws Exception{JSONObject active=WallpaperStore.active(app,1);String file=active.optString("file");long starts=0;try{JSONArray log=new JSONArray(WallpaperStore.prefs(app).getString("diagnostics","[]"));for(int i=0;i<log.length();i++)if(log.getJSONObject(i).optString("stage").equals("surface"))starts++;}catch(Exception ignored){}
  shell("am start -W -n dev.workshopvideo/.MainActivity");Thread.sleep(2200);shell("am start -W -n dev.workshopvideo.test/dev.workshopvideo.OffsetHostActivity --ei pages 3 --ei page 1");Thread.sleep(1000);check(WallpaperStore.matchesRendered(app,1,file),"return from app preserves active video");long next=0;JSONArray log=new JSONArray(WallpaperStore.prefs(app).getString("diagnostics","[]"));for(int i=0;i<log.length();i++)if(log.getJSONObject(i).optString("stage").equals("surface"))next++;check(next==starts,"brief app visit resumes decoder without rebuilding Surface");
 }
 public void onStart(){Bundle report=new Bundle();int result=Activity.RESULT_CANCELED;try{
  if(!Build.HARDWARE.equals("ranchu")&&!Build.HARDWARE.equals("goldfish"))throw new SecurityException("Refuses physical devices");app=(VideoApp)getTargetContext().getApplicationContext();output=new File(app.getExternalFilesDir(null),"service-validation");output.mkdirs();manager=WallpaperManager.getInstance(app);
  JSONObject pending=configuration("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa");getUiAutomation().adoptShellPermissionIdentity();try{WallpaperManager.class.getMethod("setWallpaperComponent",ComponentName.class).invoke(manager,new ComponentName(app,VideoWallpaperService.class));}finally{getUiAutomation().dropShellPermissionIdentity();}
  check(WallpaperStore.installed(app),"Android binds the production live wallpaper component");WallpaperStore.activate(app,pending);

  heartbeats=true;heartbeat.post(pulse);if(!inputOnly){if(!xrayOnly){frames("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","image",new int[]{2,3,5});frames("bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb","scene",new int[]{3,5});frames("cccccccccccccccccccccccccccccccc","video",new int[]{3});frames("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","image-after-video",new int[]{3});frames("cccccccccccccccccccccccccccccccc","video-after-image",new int[]{3});
  frozenOffset();}realXray();resumeCheck();}else frames("cccccccccccccccccccccccccccccccc","real-input-video",new int[]{3});realInput();check(true,"software emulator main-loop timing recorded (not phone smoothness): max gap="+maxMainDelay+" ms");report.putLong("maxMainDelayMs",maxMainDelay);
  final long[] dispatch={0};android.service.wallpaper.WallpaperService.Engine running=engine();java.lang.reflect.Method replace=running.getClass().getDeclaredMethod("start");replace.setAccessible(true);runOnMainSync(()->{long at=SystemClock.elapsedRealtime();try{replace.invoke(running);}catch(Exception e){throw new RuntimeException(e);}dispatch[0]=SystemClock.elapsedRealtime()-at;});check(dispatch[0]<500,"wallpaper replacement dispatch does not wait for decoder teardown: "+dispatch[0]+" ms");report.putLong("replaceDispatchMs",dispatch[0]);
  report.putString("result","PASS");result=Activity.RESULT_OK;
 }catch(Throwable e){report.putString("result","FAIL");report.putString("error",android.util.Log.getStackTraceString(e));android.util.Log.e("ServiceChecks","Failed",e);}finally{heartbeats=false;heartbeat.removeCallbacks(pulse);if(host!=null)runOnMainSync(host::finish);try{if(output!=null)Files.write(new File(output,"results.json").toPath(),new JSONObject().put("result",report.getString("result")).put("error",report.getString("error","")).put("checks",checks).put("api",Build.VERSION.SDK_INT).put("maxMainDelayMs",maxMainDelay).put("passed",passed).toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8));}catch(Exception ignored){}report.putInt("checks",checks);finish(result,report);}}
}
